// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(115000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const errors: Error[] = [];
    const page1 = await page.context().newPage();
    page1.on('pageerror', (e) => errors.push(e));
    await page1.waitForURL(baseUrl);
    await page1.getByTestId("main-menu-trigger").click();
    await page1.getByTestId("image-export-button").click();
    await expect(page1.getByRole("heading", { name: "Export image" })).toBeVisible();
    await expect(page1.getByRole("button", { name: "Export to PNG" })).toBeVisible();
    await expect(page1.getByRole("button", { name: "Export to SVG" })).toBeVisible();
    await expect(page1.getByRole("button", { name: "Copy PNG to clipboard" })).toBeVisible();
    await expect(page1.getByTestId("export-error-state")).not.toBeVisible();
    await expect(errors).toHaveLength(0);
});
